<script setup>
import{ref}from'vue';import ConfirmDialog from'./ConfirmDialog.vue';import{getAction}from'../utils/actions'
const props=defineProps({records:{type:Array,default:()=>[]},writingRecords:{type:Array,default:()=>[]},title:{type:String,default:'当天记录'}});const emit=defineEmits(['delete']);const expanded=ref(''),pendingDelete=ref('');const moodEmoji={很好:'😄',不错:'🙂',一般:'😐',低落:'😔',很难受:'😣'}
function time(value){return new Intl.DateTimeFormat('zh-CN',{hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(value))}function confirmDelete(){emit('delete',pendingDelete.value);if(expanded.value===pendingDelete.value)expanded.value='';pendingDelete.value=''}function recordWritings(record){const ids=new Set(record.writingRecordIds||[]);return props.writingRecords.filter(item=>item.sourceType==='emotion'&&item.sourceRecordId===record.id&&(ids.size===0||ids.has(item.id)))}
</script>
<template><section class="history-section"><div class="section-heading"><div><p class="eyebrow">每日回看</p><h2>{{title}}</h2></div><p v-if="records.length">共 {{records.length}} 条</p></div><div v-if="records.length" class="history-list"><article v-for="record in records" :key="record.id" :class="['history-item',{expanded:expanded===record.id}]"><button class="history-summary" type="button" :aria-expanded="expanded===record.id" @click="expanded=expanded===record.id?'':record.id"><div class="history-date"><strong>{{time(record.createdAt)}}</strong><span>记录时间</span></div><div class="history-main"><h3>{{moodEmoji[record.mood]}} {{record.mood}} <span>· {{record.intensity}}/10</span></h3><div class="mini-tags"><span v-for="tag in record.emotionTags.slice(0,3)" :key="tag">{{tag}}</span></div><p class="history-context">{{record.triggerTags.join(' / ')||'未选择触发因素'}}</p><p class="history-note">{{record.note||'这次没有留下文字。'}}</p></div><span class="expand-mark">{{expanded===record.id?'−':'+'}}</span></button><Transition name="fade"><div v-if="expanded===record.id" class="history-detail"><div><span>当时写下</span><p>{{record.note||'这次没有留下文字。'}}</p></div><div class="detail-grid"><div><span>情绪感受</span><p>{{record.emotionTags.join('、')||'未选择'}}</p></div><div><span>触发因素</span><p>{{record.triggerTags.join('、')||'未选择'}}</p></div><div><span>当时需要</span><p>{{record.need||record.positiveChoice||'未选择'}}</p></div><div><span>实际选择</span><p v-if="record.selectedActionId">{{getAction(record.selectedActionId).icon}} {{record.selectedActionLabel||getAction(record.selectedActionId).label}}</p><p v-else>这次没有选择关怀行动。</p></div></div><div class="saved-insight"><span>当时的洞察</span><p>{{record.insightSummary||'这条旧记录没有保存洞察摘要。'}}</p></div><div v-if="record.careActivities?.length" class="activity-history"><span>你做了</span><article v-for="activity in record.careActivities" :key="activity.id"><p><strong>{{getAction(activity.actionId).icon}} {{activity.actionName}}</strong> · 已完成</p></article></div><div v-if="recordWritings(record).length" class="activity-history writing-in-history"><span>关联书写</span><article v-for="item in recordWritings(record)" :key="item.id"><small>书写问题</small><blockquote>{{item.prompt}}</blockquote><small>我的回答</small><blockquote>{{item.answer}}</blockquote></article></div><button class="delete-link" type="button" @click="pendingDelete=record.id">删除这条记录</button></div></Transition></article></div><div v-else class="empty-state compact"><span>◌</span><h3>这一天还没有记录</h3><p>没有记录也很自然，可以看看其他日期。</p></div><ConfirmDialog :open="!!pendingDelete" @cancel="pendingDelete=''" @confirm="confirmDelete"/></section></template>
